import os, pty, select, termios, tty, fcntl, struct, time, sys, re

class Screen:
    def __init__(self, rows=40, cols=120):
        self.rows=rows; self.cols=cols
        self.buf=[[' ']*cols for _ in range(rows)]
        self.r=0; self.c=0
    def put(self,ch):
        if ch=='\\n':
            self.r=min(self.rows-1,self.r+1); self.c=0; return
        if ch=='\\r':
            self.c=0; return
        if ch=='\\b':
            self.c=max(0,self.c-1); return
        if ord(ch)<32:
            return
        if 0<=self.r<self.rows and 0<=self.c<self.cols:
            self.buf[self.r][self.c]=ch
        if self.c<self.cols-1:
            self.c+=1
    def move(self,row,col):
        self.r=max(0,min(self.rows-1,row))
        self.c=max(0,min(self.cols-1,col))
    def clear(self):
        self.buf=[[' ']*self.cols for _ in range(self.rows)]
        self.r=self.c=0
    def line_clear(self, mode=0):
        if mode==2:
            self.buf[self.r]=[' ']*self.cols
        elif mode==0:
            for i in range(self.c,self.cols): self.buf[self.r][i]=' '
        elif mode==1:
            for i in range(0,self.c+1): self.buf[self.r][i]=' '
    def dump(self):
        return '\\n'.join(''.join(row).rstrip() for row in self.buf).rstrip()\\

scr=Screen(40,120)

def process(data):
    i=0
    while i<len(data):
        ch=data[i]
        if ch==0x1b and i+1<len(data):
            if data[i+1]==ord('['):
                j=i+2
                while j<len(data) and not (0x40<=data[j]<=0x7e):
                    j+=1
                if j>=len(data):
                    break
                seq=data[i+2:j].decode('utf-8','ignore')
                cmd=chr(data[j])
                if cmd in 'Hf':
                    parts=seq.split(';') if seq else []
                    row=int(parts[0]) if len(parts)>=1 and parts[0] else 1
                    col=int(parts[1]) if len(parts)>=2 and parts[1] else 1
                    scr.move(row-1,col-1)
                elif cmd=='J':
                    mode=int(seq or '0')
                    if mode==2:
                        scr.clear()
                elif cmd=='K':
                    mode=int(seq or '0')
                    scr.line_clear(mode)
                elif cmd in 'mhl?':
                    pass
                else:
                    pass
                i=j+1
                continue
            else:
                i+=2
                continue
        scr.put(chr(ch))
        i+=1

pid, fd = pty.fork()
if pid==0:
    os.environ['COLUMNS']='80'
    os.environ['LINES']='20'
    os.execv('/workspace/executable', ['/workspace/executable','--nokb','-n','2','-t','5','-c','1','-r','1','-w','1','-a','0'])
# set window size
fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH',20,80,0,0))
end=time.time()+1.0
while time.time()<end:
    r,_,_=select.select([fd],[],[],0.1)
    if fd in r:
        try:
            data=os.read(fd,4096)
        except OSError:
            break
        if not data: break
        process(data)
# send esc to quit
os.write(fd,b'\\x1b')
time.sleep(0.2)
while True:
    r,_,_=select.select([fd],[],[],0.1)
    if fd in r:
        try:data=os.read(fd,4096)
        except OSError: break
        if not data: break
        process(data)
    else:
        break
os.close(fd)
print(scr.dump())
