def validate_options(opts: Options) -> None:
    if not 1 <= opts.top <= 200:
        sys.stdout.write("Invalid argument for top. Use a number between 1 and 200.\n")
        raise SystemExit(1)
    if not 1 <= opts.combi <= 200:
        sys.stdout.write("Invalid argument for combi. Use a number between 1 and 200.\n")
        raise SystemExit(1)
    if not 1 <= opts.rep <= 200:
        sys.stdout.write("Invalid argument for rep. Use a number between 1 and 200.\n")
        raise SystemExit(1)
    if not 1 <= opts.wpm <= 200:
        sys.stdout.write("Invalid argument for wpm. Use a number between 1 and 200.\n")
        raise SystemExit(1)
    if not 0 <= opts.acc <= 100:
        sys.stdout.write("Invalid argument for acc. Use a number between 0 and 100.\n")
        raise SystemExit(1)
    if bool(opts.emu_in) != bool(opts.emu_out):
        sys.stdout.write("You need to specify both emu_in and emu_out.\n")
        raise SystemExit(1)
    if opts.n not in {"2", "3", "4", "w"} and not os.path.exists(opts.n):
        sys.stdout.write(f"File not found: {opts.n}\n")
        raise SystemExit(1)


def load_custom_words(path: str) -> list[str]:
    content = open(path, "r", encoding="utf-8").read()
    if "," in content:
        return [token.rstrip("\r\n") for token in content.split(",") if token.rstrip("\r\n") != ""]
    return content.split()


def get_pool(opts: Options) -> list[str]:
    if opts.n == "2":
        return BIGRAMS[:]
    if opts.n == "3":
        return TRIGRAMS[:]
    if opts.n == "4":
        return TETRAGRAMS[:]
    if opts.n == "w":
        return WORDS[:]
    return load_custom_words(opts.n)


def get_layout_rows(name: str) -> list[str]:
    return LAYOUTS.get(name.lower(), LAYOUTS["qwerty"])["display"]


def build_translation(input_rows: list[str], output_rows: list[str]) -> dict[str, str]:
    mapping: dict[str, str] = {}
    for in_row, out_row in zip(input_rows, output_rows):
        for index, ch in enumerate(in_row):
            if index < len(out_row):
                mapping[ch] = out_row[index]
    return mapping


def build_lesson(pool: list[str], combi: int, rep: int) -> Lesson:
    if not pool:
        return Lesson("", "")
    selected = [random.choice(pool) for _ in range(combi)]
    expected = "".join(f"{token} " for _ in range(rep) for token in selected)
    return Lesson(expected.rstrip(" "), expected)


def center_text(text: str, width: int) -> str:
    if len(text) >= width:
        return text[:width]
    pad = (width - len(text)) // 2
    return " " * pad + text + " " * (width - len(text) - pad)


def blank_line() -> str:
    return "│" + " " * 77 + "│"


def separator_line() -> str:
    return "│" + "─" * 77 + "│"


def border_top() -> str:
    return "╭" + "─" * 65 + " Quit <esc> " + "╮"


def border_bottom() -> str:
    return "╰" + "─" * 77 + "╯"


def metric_line(label: str, need: int, avg: int, last: int) -> str:
    if label == "WPM":
        body = f"  need >= {need:>3}WPM,   avg. {avg:>3}WPM,   last {last:>3}WPM"
    else:
        body = f"  need >= {need:>3}% Acc, avg. {avg:>3}% Acc, last {last:>3}% Acc"
    return "│" + body.ljust(77) + "│"


