            "┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐",
            "│ " + " │ ".join(rows[0]) + " │",
            "├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤",
