            "│ " + " │ ".join(rows[2] + "△△") + " │",
            "└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘",
        ]
    else:
        row1 = "┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐"
        row2 = "│ " + " │ ".join(rows[0]) + " │"
        row3 = "└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘"
        row4 = " │ " + " │ ".join(rows[1]) + " │"
        row5 = " └┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘"
        row6 = "  │ " + " │ ".join(rows[2]) + " │"
        row7 = "  └───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘"
        key_rows = [row1, row2, row3, row4, row5, row6, row7]
    left_pad = 5 if cat else (77 - len(key_rows[0])) // 2
    return ["│" + (" " * left_pad + row).ljust(77) + "│" for row in key_rows]


def overlay(base: str, text: str, column: int) -> str:
    if column >= len(base):
        return base
    chars = list(base)
    for index, ch in enumerate(text):
        pos = column + index
        if 0 <= pos < len(chars):
            chars[pos] = ch
    return "".join(chars)


def render_cat(lines: list[str], show_ortho: bool) -> list[str]:
    cat_art = {
        10: "          /\\_/\\\\",
        11: "         >(•༝• )<",
        12: "         |    \\",
        13: "         || |  )",
        14: "         ll-l-//",
        15: " /▔▔▔▔▔▔▔▔\\\\▔▔\\",
        16: "        \\__>",
    }
    for row, art in cat_art.items():
        if row < len(lines):
            lines[row] = overlay(lines[row], art, 57)
    return lines


def panic_screen(lines: list[str]) -> list[str]:
    if len(lines) > 7:
        lines[7] = "│" + PANIC_LINES[0].ljust(77)[:77] + "│"
    if len(lines) > 8:
        lines[8] = "│" + PANIC_LINES[1].ljust(77)[:77] + "│"
    if len(lines) > 9:
        lines[9] = "│" + PANIC_LINES[2].ljust(77)[:77] + "│"
    return lines


def build_mistake_overlay(state: GameState) -> str:
    if not state.lesson:
        return ""
    if not state.typed_actual:
        return ""
    chars = [" "] * len(state.lesson.visible)
    for position, value in state.typed_actual.items():
        if 0 <= position < len(chars):
            chars[position] = value
    return "".join(chars).rstrip()


def render_prompt(state: GameState) -> str:
    if not state.lesson:
        return ""
    visible = state.lesson.visible
    if state.cursor >= len(visible):
        return visible + "•"
    return visible


def render(state: GameState, panic: bool = False) -> str:
    lesson_number = state.lesson_count if state.lesson is not None else 0
    header = f"    Lesson #{lesson_number}"
    score = f"✔: {state.success_count}, ✘: {state.failure_count}    "
    line4 = "│" + header.ljust(77 - len(score)) + score + "│"
    lines = [
        border_top(),
        "│" + center_text("ngrrram!   by winterveil", 77) + "│",
        separator_line(),
        line4,
        separator_line(),
        blank_line(),
        "│" + center_text(render_prompt(state), 77) + "│",
        "│" + center_text(build_mistake_overlay(state), 77) + "│",
    ]
    if state.options.nokb:
        lines.extend([
            blank_line(),
            separator_line(),
            metric_line("WPM", state.options.wpm, state.avg_wpm, state.last_wpm),
            metric_line("ACC", state.options.acc, state.avg_acc, state.last_acc),
            border_bottom(),
        ])
    else:
        keyboard = render_keyboard(state.output_layout, state.options.show_ortho, state.options.cat)
        lines.extend(keyboard)
        lines.append(separator_line())
        lines.append(metric_line("WPM", state.options.wpm, state.avg_wpm, state.last_wpm))
        lines.append(metric_line("ACC", state.options.acc, state.avg_acc, state.last_acc))
        lines.append(border_bottom())
        if state.options.cat:
            lines = render_cat(lines, state.options.show_ortho)
    if panic:
        lines = panic_screen(lines)
    return "\x1b[H" + "\n".join(lines)


def complete_lesson(state: GameState) -> None:
    elapsed = max(time.monotonic() - (state.started_at or time.monotonic()), 0.001)
    nonspace = sum(1 for ch in state.lesson.expected if ch != " ")
    wpm = round(((nonspace / 5.0) * 60.0) / elapsed)
    acc = round((state.good_presses / max(state.total_presses, 1)) * 100)
    state.last_wpm = wpm
    state.last_acc = acc
    state.wpm_history.append(wpm)
    state.acc_history.append(acc)
    state.avg_wpm = round(sum(state.wpm_history) / len(state.wpm_history))
    state.avg_acc = round(sum(state.acc_history) / len(state.acc_history))
    if wpm >= state.options.wpm and acc >= state.options.acc:
        state.success_count += 1
    else:
        state.failure_count += 1
    state.lessons_done += 1
    state.reset_for_next_lesson()


def apply_input_char(state: GameState, raw_char: str, translate: dict[str, str]) -> None:
    if raw_char in ("\x08", "\x7f"):
        state.total_presses += 1
        current = state.mistakes.get(state.cursor)
        if current:
            current.pop()
            if current:
                state.typed_actual[state.cursor] = current[-1]
            else:
                state.mistakes.pop(state.cursor, None)
                state.typed_actual.pop(state.cursor, None)
            state.good_presses += 1
        return
    if not state.lesson or raw_char == "\x1b":
        return
    if len(raw_char) != 1 or ord(raw_char) < 32 or ord(raw_char) > 126:
        return
    mapped = translate.get(raw_char, raw_char)
    expected = state.lesson.expected[state.cursor] if state.cursor < len(state.lesson.expected) else ""
    if state.started_at is None:
        state.started_at = time.monotonic()
    state.total_presses += 1
    if mapped == expected:
        state.good_presses += 1
        if state.cursor < len(state.lesson.visible):
            state.typed_actual[state.cursor] = mapped
        state.cursor += 1
        if state.cursor >= len(state.lesson.expected):
            if not state.mistakes:
                complete_lesson(state)
            else:
                state.cursor = len(state.lesson.visible)
        return
    state.mistakes.setdefault(state.cursor, []).append(mapped)
    state.typed_actual[state.cursor] = mapped


def read_input(timeout: float = 0.05) -> str | None:
    ready, _, _ = select.select([sys.stdin], [], [], timeout)
    if not ready:
        return None
    data = os.read(sys.stdin.fileno(), 32)
    if not data:
        return "\x1b"
    return data.decode("utf-8", "ignore")


def run_game(opts: Options, pool: list[str]) -> int:
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        sys.stdout.write(TTY_ERROR + "\n")
        return 1
    output_layout = get_layout_rows(opts.emu_out or "qwerty")
    input_layout = get_layout_rows(opts.emu_in or "qwerty")
    translate = build_translation(input_layout, output_layout)
    state = GameState(
        options=opts,
        pool=pool[: max(1, min(opts.top, len(pool)))],
        output_layout=output_layout,
        input_layout=input_layout,
    )
    ui = TerminalUI()
    ui.enter()
    try:
        if not state.pool:
            sys.stdout.write(render(state, panic=True))
            sys.stdout.flush()
            return 101
        state.reset_for_next_lesson()
        sys.stdout.write(render(state))
        sys.stdout.flush()
        while not state.quitting:
            data = read_input()
            if data is None:
                continue
            for char in data:
                if char == "\x1b":
                    state.quitting = True
                    break
                apply_input_char(state, char, translate)
            sys.stdout.write(render(state))
            sys.stdout.flush()
        return 0
    finally:
        ui.leave()


def main() -> int:
    try:
        opts = parse_args(sys.argv[1:])
    except SystemExit as exc:
        return int(exc.code)
    validate_options(opts)
    pool = get_pool(opts)
    return run_game(opts, pool)


if __name__ == "__main__":
    raise SystemExit(main())

